-- LABLAB MOTORSHOP - Supabase/PostgreSQL schema
-- Run this whole file once in Supabase SQL Editor.
create extension if not exists pgcrypto;

create table if not exists public.branches (
  branch_id bigint generated by default as identity primary key,
  branch_name text not null unique,
  address text,
  contact_no text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists public.part_categories (
  category_id bigint generated by default as identity primary key,
  category_name text not null unique,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists public.suppliers (
  supplier_id bigint generated by default as identity primary key,
  supplier_name text not null,
  contact_person text,
  phone text,
  email text,
  address text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists public.parts (
  part_id bigint generated by default as identity primary key,
  part_name text not null,
  part_number text,
  description text,
  category_id bigint references public.part_categories(category_id) on delete set null,
  unit_price numeric(12,2) not null default 0 check(unit_price>=0),
  reorder_quantity integer not null default 10 check(reorder_quantity>=0),
  reorder_level integer not null default 5 check(reorder_level>=0),
  supplier_id bigint references public.suppliers(supplier_id) on delete set null,
  is_available boolean not null default true,
  image_path text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  username text unique,
  email text,
  first_name text not null default '',
  last_name text not null default '',
  role text not null default 'customer' check(role in ('admin','staff','customer')),
  branch_id bigint references public.branches(branch_id) on delete set null,
  phone text,
  address text,
  profile_image text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists public.customers (
  customer_id bigint generated by default as identity primary key,
  user_id uuid not null unique references public.profiles(id) on delete cascade,
  first_name text not null default '', last_name text not null default '', email text, phone text, address text,
  is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.stock_levels (
  stock_level_id bigint generated by default as identity primary key,
  part_id bigint not null references public.parts(part_id) on delete cascade,
  branch_id bigint not null references public.branches(branch_id) on delete cascade,
  quantity_on_hand integer not null default 0 check(quantity_on_hand>=0),
  quantity_reserved integer not null default 0 check(quantity_reserved>=0),
  updated_at timestamptz not null default now(), unique(part_id,branch_id)
);
create table if not exists public.stock_history (
  stock_history_id bigint generated by default as identity primary key,
  part_id bigint not null references public.parts(part_id), branch_id bigint not null references public.branches(branch_id),
  transaction_type text not null check(transaction_type in ('ADD','DEDUCT')), quantity_change integer not null,
  reference_id bigint, reference_type text, notes text, created_by uuid references public.profiles(id), created_at timestamptz not null default now()
);
create table if not exists public.booking (
  booking_id bigint generated by default as identity primary key,
  customer_id bigint not null references public.customers(customer_id), branch_id bigint not null references public.branches(branch_id),
  booking_date timestamptz not null default now(), reserved_until timestamptz, status text not null default 'pending' check(status in ('pending','confirmed','cancelled','completed')),
  total_amount numeric(12,2) not null default 0, notes text, created_by uuid references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.booking_items (
  booking_item_id bigint generated by default as identity primary key, booking_id bigint not null references public.booking(booking_id) on delete cascade,
  part_id bigint not null references public.parts(part_id), quantity integer not null check(quantity>0), unit_price numeric(12,2) not null, subtotal numeric(12,2) not null
);
create table if not exists public.transactions (
  transaction_id bigint generated by default as identity primary key, customer_id bigint references public.customers(customer_id), booking_id bigint references public.booking(booking_id),
  branch_id bigint not null references public.branches(branch_id), transaction_date timestamptz not null default now(), transaction_type text not null check(transaction_type in ('DIRECT_SALE','BOOKING_SALE')),
  total_amount numeric(12,2) not null, payment_method text not null check(payment_method in ('CASH','CREDIT_CARD','GCASH','BANK_TRANSFER')),
  payment_status text not null default 'pending' check(payment_status in ('pending','paid','refunded')), notes text, processed_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.transaction_items (
  transaction_item_id bigint generated by default as identity primary key, transaction_id bigint not null references public.transactions(transaction_id) on delete cascade,
  part_id bigint not null references public.parts(part_id), quantity integer not null check(quantity>0), unit_price numeric(12,2) not null, subtotal numeric(12,2) not null
);

insert into public.branches(branch_name,address,contact_no) values
('Kidapawan Branch','Kidapawan City, Cotabato','0900-000-0001'),('Magpet Branch','Magpet, Cotabato','0900-000-0002'),('Manongol Branch','Manongol, Cotabato','0900-000-0003') on conflict(branch_name) do nothing;
